const API='https://fgomaujsdblpzxhnnqrg.supabase.co/rest/v1/';
const KEY='sb_publishable_JOUqLZDnfGu_yCa6k6FVDQ_AYwpr72i';
const PREFIX='gant02_20261024_';
const $=id=>document.getElementById(id), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const DAY=86400000, date=s=>new Date(s+'T12:00:00Z'), iso=d=>d.toISOString().slice(0,10), add=(s,n)=>iso(new Date(+date(s)+n*DAY)), diff=(a,b)=>Math.round((date(a)-date(b))/DAY);
const localToday=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
const label={assigned:'Assigned',in_progress:'In progress',done:'Complete'};
let projects=[],tasks=[],collapsed=new Set(),start=add(localToday(),-7),days=120,cw=26,pending=0,loading=false,loaded=false,editor=null,editorBaseline='',draggingId=null,draggingKind=null,pointer=null,suppressClick=false;
const drafts=new Map(),creatingRows=new Set();
let cells=new Map(),paintMode='assigned',paintQueue=Promise.resolve(),paintNeedsReload=false;
const status=(s,failed=false)=>{$('sync').textContent=s;$('sync').classList.toggle('failed',failed);};
function error(e){$('error').textContent=e.message||String(e);$('error').hidden=false;status('Could not sync',true);}
function toast(s){$('toast').textContent=s;$('toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').hidden=true,2600);}
async function api(table,method='GET',body=null,query=''){
 const response=await fetch(API+PREFIX+table+query,{method,headers:{apikey:KEY,'Content-Type':'application/json',Prefer:'return=representation,resolution=merge-duplicates'},...(body?{body:JSON.stringify(body)}:{})});
 if(!response.ok){const e=await response.json().catch(()=>({message:response.statusText}));throw Error(e.message||'Database request failed');}return response.status===204?[]:response.json();
}
async function load(quiet=false){if(loading||pending||pointer)return;loading=true;if(!quiet)status('Syncing…');try{const [p,t,c]=await Promise.all([api('projects','GET',null,'?select=*&order=position,created_at'),api('tasks','GET',null,'?select=*&order=position,created_at'),loadCells()]);projects=p;tasks=t;cells=new Map(c.map(x=>[x.task_id+'/'+x.day,x]));loaded=true;render();status('All changes saved');$('error').hidden=true;}catch(e){error(e);}finally{loading=false;}}
async function mutate(table,method,body,id){pending++;status('Saving…');try{const result=await api(table,method,body,id?'?id=eq.'+encodeURIComponent(id):'');$('error').hidden=true;return result;}catch(e){error(e);throw e;}finally{pending--;if(!pending&&$('error').hidden)status('All changes saved');}}
async function updateTask(id,patch){const task=tasks.find(t=>t.id===id);if(!task)return;const old={...task};Object.assign(task,patch);render();try{const [saved]=await mutate('tasks','PATCH',patch,id);if(!saved)throw Error('Task was removed. Refresh to continue.');Object.assign(task,saved);render();}catch(e){Object.assign(task,old);render();error(e);}}
function visible(t){return (!$('status-filter').value||(t.status===$('status-filter').value||[...cells.values()].some(c=>c.task_id===t.id&&c.status===$('status-filter').value)))&&(!q()||[t.name,t.assignee,projects.find(p=>p.id===t.project_id)?.name].join(' ').toLowerCase().includes(q()));}
function q(){return $('search').value.trim().toLowerCase();}
function options(selected){return projects.map(p=>`<option value="${p.id}" ${p.id===selected?'selected':''}>${esc(p.name)}</option>`).join('');}
function bands(){let h='';for(let i=0;i<days;i++){const d=add(start,i);if([0,6].includes(date(d).getUTCDay()))h+=`<span class="weekend-band" style="left:${i*cw}px;width:${cw}px"></span>`;}const today=diff(localToday(),start);if(today>=0&&today<days)h+=`<span class="today-line" style="left:${today*cw+cw/2}px"></span>`;return h;}
function spanHTML(s,e,project=false,t=null){if(!s||!e)return '';const x=diff(s,start),n=diff(e,s)+1;if(x+n<=0||x>=days)return '';const left=Math.max(0,x)*cw+2,width=(Math.min(days,x+n)-Math.max(0,x))*cw-4;if(project)return `<span class="project-span" style="left:${left}px;width:${width}px"></span>`;return `<div class="bar ${t.status}" data-id="${t.id}" role="button" tabindex="0" aria-label="${esc(t.name)}, ${s} to ${e}, ${label[t.status]}. Arrow keys move one day; Shift and arrow keys resize." title="${esc(t.name)} · ${s} → ${e}" style="left:${left}px;width:${width}px"><span class="resize left" data-edge="start"></span><span class="bar-label">${esc(t.name)}</span><span class="resize right" data-edge="end"></span></div>`;}
function render(){
 const filter=$('project-filter').value;$('project-filter').innerHTML='<option value="">All projects</option>'+options(filter);$('new-task').disabled=!projects.length||!loaded;$('new-project').disabled=!loaded;
 const dayHeaders=[];for(let i=0;i<days;i++){const d=add(start,i),dt=date(d),month=dt.toLocaleDateString('en-US',{month:'short',year:'numeric',timeZone:'UTC'}),weekday=dt.toLocaleDateString('en-US',{weekday:'short',timeZone:'UTC'}).toUpperCase();dayHeaders.push(`<div class="date-column ${[0,6].includes(dt.getUTCDay())?'weekend':''} ${d===localToday()?'today':''}" title="${d}"><span class="sheet-letter">${columnName(i+2)}</span><span class="header-band"></span><span class="vertical-month">${month}</span><span class="weekday">${weekday}</span><span class="day-number">${String(dt.getUTCDate()).padStart(2,'0')}</span></div>`);}
 const width=days*cw,band=bands();let h=`<div class="grid-header"><div class="frozen"><div class="col-head" aria-hidden="true"></div><div class="col-head"><span class="name-column-letter">A</span>Task / project</div></div><div class="calendar date-columns" style="width:${width}px">${dayHeaders.join('')}</div></div>`;
 let count=0;for(const p of projects.filter(p=>!filter||p.id===filter)){
 const all=tasks.filter(t=>t.project_id===p.id),rows=all.filter(visible);if((q()||$('status-filter').value)&&!rows.length)continue;const dates=all.filter(t=>t.start_date),s=dates.length?dates.map(t=>t.start_date).sort()[0]:null,e=dates.length?dates.map(t=>t.end_date).sort().at(-1):null;
 h+=`<div class="row project-row" data-project="${p.id}"><div class="frozen" draggable="true" data-drag-project="${p.id}" title="Drag to reorder project"><button class="collapse" data-collapse="${p.id}" aria-label="${collapsed.has(p.id)?'Expand':'Collapse'} project">${collapsed.has(p.id)?'▸':'▾'}</button><button class="project-name" data-open-project="${p.id}">${esc(p.name)}</button></div><div class="timeline" style="width:${width}px">${spanHTML(s,e,true)}</div></div>`;
 if(collapsed.has(p.id))continue;
 for(const t of rows){count++;h+=`<div class="row task-row" data-task="${t.id}" data-project="${p.id}"><div class="frozen"><div class="cell row-spacer" aria-hidden="true"></div><div class="cell name-cell" draggable="true" data-drag-task="${t.id}" title="Drag to reorder or move between projects"><span class="task-status dot ${t.status}" title="${label[t.status]}"></span><button data-open="${t.id}" title="Open task details">${esc(t.name)}</button>${t.notes?'<span class="note-mark" title="Has notes">≡</span>':''}</div></div><div class="timeline task-timeline" data-id="${t.id}" style="width:${width}px">${band}${paintMode!==null?dateSquares(t):spanHTML(t.start_date,t.end_date,false,t)}</div></div>`;}
 h+=blankRow('task',p.id,width,band);
 }
 h+=blankRow('project','',width,band);
 if(projects.length&&!count&&(q()||$('status-filter').value))h+='<div class="empty"><h2>No matching tasks</h2><p>Try another search or clear your filters.</p></div>';
 $('grid').innerHTML=h;$('summary').textContent=`${projects.length} project${projects.length===1?'':'s'} · ${tasks.length} tasks · ${tasks.filter(t=>t.status==='done').length} completed`;$('task-count').textContent=`${count} visible tasks`;$('range-label').textContent=date(start).toLocaleDateString('en-US',{month:'short',year:'numeric',timeZone:'UTC'});document.documentElement.style.setProperty('--day',cw+'px');
}
function columnName(n){let s='';while(n){n--;s=String.fromCharCode(65+n%26)+s;n=Math.floor(n/26);}return s;}
function blankRow(type,projectId,width,band){const key=type==='project'?'project':projectId;return `<div class="row inline-create-row ${type==='project'?'new-project-row':''}" ${projectId?`data-project="${projectId}"`:''}><div class="frozen"><span class="cell new-row-mark">＋</span><div class="cell"><input class="inline-create" data-create="${type}" data-project-id="${projectId}" data-key="${key}" value="${esc(drafts.get(key)||'')}" aria-label="${type==='project'?'New project name':'New task name in '+projects.find(p=>p.id===projectId)?.name}" placeholder="${type==='project'?'New project…':'New task…'}" title="Type a name, then press Enter or Tab to create" maxlength="200" autocomplete="off" ${creatingRows.has(key)?'disabled':''}></div></div><div class="timeline" style="width:${width}px">${band}</div></div>`;}
function create(type,project){if(type==='task'){project=project||$('project-filter').value||projects[0]?.id;if(!project)return;collapsed.delete(project);$('search').value='';$('status-filter').value='';}render();const input=[...document.querySelectorAll('.inline-create')].find(x=>x.dataset.create===type&&(type==='project'||x.dataset.projectId===project));input?.focus();input?.scrollIntoView?.({block:'nearest',inline:'nearest'});}
async function createInline(input,refocus=false){const {create:type,projectId,key}=input.dataset,name=input.value.trim();if(!name||creatingRows.has(key)||!loaded)return;creatingRows.add(key);input.disabled=true;const table=type==='project'?'projects':'tasks',items=type==='project'?projects:tasks,payload={name,position:Math.max(0,...items.map(x=>x.position))+1024};if(type==='task')payload.project_id=projectId;try{const [item]=await mutate(table,'POST',payload);items.push(item);drafts.delete(key);creatingRows.delete(key);if(type==='project')$('project-filter').value='';$('search').value='';$('status-filter').value='';render();if(refocus){const next=[...document.querySelectorAll('.inline-create')].find(x=>x.dataset.key===(type==='project'?item.id:key));next?.focus();}}catch{creatingRows.delete(key);input.disabled=false;if(refocus)input.focus();}}
$('new-project').onclick=()=>create('project');$('new-task').onclick=()=>create('task');
$('grid').addEventListener('input',e=>{if(e.target.matches('.inline-create'))drafts.set(e.target.dataset.key,e.target.value);});
$('grid').addEventListener('focusout',e=>{if(e.target.matches('.inline-create'))createInline(e.target);});
$('grid').addEventListener('keydown',e=>{if(!e.target.matches('.inline-create'))return;if(e.key==='Enter'){e.preventDefault();createInline(e.target,true);}if(e.key==='Escape'){e.target.value='';drafts.delete(e.target.dataset.key);e.target.blur();}});
for(const id of ['project-filter','status-filter','search'])$(id).addEventListener(id==='search'?'input':'change',render);
$('refresh').onclick=()=>load();$('zoom').onchange=()=>{cw=Number($('zoom').value);render();};$('prev').onclick=()=>{start=add(start,-28);render();};$('next').onclick=()=>{start=add(start,28);render();};$('today').onclick=()=>{start=add(localToday(),-7);$('grid-wrap').scrollLeft=0;render();};
$('grid').addEventListener('click',e=>{if(suppressClick)return;const a=e.target.closest('button');if(a?.dataset.open)openEditor('tasks',a.dataset.open);else if(a?.dataset.openProject)openEditor('projects',a.dataset.openProject);else if(a?.dataset.add)create('task',a.dataset.add);else if(a?.dataset.collapse){const id=a.dataset.collapse;collapsed.has(id)?collapsed.delete(id):collapsed.add(id);render();}});
async function loadCells(){let rows=[],offset=0;while(true){const page=await api('cells','GET',null,'?select=*&order=task_id,day&limit=1000&offset='+offset);rows.push(...page);if(page.length<1000)return rows;offset+=1000;}}
function dayStatus(t,day){const explicit=cells.get(t.id+'/'+day);return explicit?explicit.status:(t.start_date&&day>=t.start_date&&day<=t.end_date?t.status:null);}
function dateSquares(t){let h='';for(let i=0;i<days;i++){const day=add(start,i),value=dayStatus(t,day);h+=`<button class="date-square ${value||''}" data-task-id="${t.id}" data-day="${day}" data-index="${i}" tabindex="${i===0?'0':'-1'}" aria-label="${esc(t.name)}, ${day}: ${label[value]||'Blank'}" title="${day} · ${label[value]||'Blank'}" style="left:${i*cw}px;width:${cw}px"></button>`;}return h;}
function paintPreview(p){const a=Math.min(p.index,p.endIndex??p.index),b=Math.max(p.index,p.endIndex??p.index);for(const square of p.line.querySelectorAll('.date-square')){const selected=Number(square.dataset.index)>=a&&Number(square.dataset.index)<=b;square.classList.toggle('painting',selected);square.style.setProperty('--paint-color',paintMode==='erase'?'#ffffff':({assigned:'#6d8fc3',in_progress:'#d59b38',done:'#4b9b78'}[paintMode]));}}
function paintDates(id,a,b){const value=paintMode==='erase'?null:paintMode,rows=[];for(let i=a;i<=b;i++)rows.push({task_id:id,day:add(start,i),status:value});for(const row of rows)cells.set(id+'/'+row.day,row);render();pending++;status('Saving…');paintQueue=paintQueue.then(async()=>{try{await api('cells','POST',rows,'?on_conflict=task_id,day');if(!paintNeedsReload)$('error').hidden=true;}catch(e){paintNeedsReload=true;error(e);toast('Color could not be saved. Please try again.');}finally{pending--;if(!pending&&paintNeedsReload){try{const saved=await loadCells();cells=new Map(saved.map(x=>[x.task_id+'/'+x.day,x]));paintNeedsReload=false;}catch{}}render();if(!pending&&$('error').hidden)status('All changes saved');}});return paintQueue;}
$('paint-tools').addEventListener('click',e=>{const button=e.target.closest('[data-paint]');if(!button)return;paintMode=button.dataset.paint==='schedule'?null:button.dataset.paint;for(const b of $('paint-tools').querySelectorAll('[data-paint]'))b.setAttribute('aria-pressed',String(b===button));render();});
$('grid').addEventListener('keydown',e=>{const square=e.target.closest('.date-square');if(!square)return;const index=Number(square.dataset.index);if(['Enter',' ','Delete','Backspace'].includes(e.key)){e.preventDefault();const previous=paintMode;if(e.key==='Delete'||e.key==='Backspace')paintMode='erase';paintDates(square.dataset.taskId,index,index);paintMode=previous;document.querySelector(`[data-task-id="${square.dataset.taskId}"][data-index="${index}"]`)?.focus();}else if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();square.parentElement.querySelector(`[data-index="${index+(e.key==='ArrowRight'?1:-1)}"]`)?.focus();}});
function cellAt(ev,el){return Math.max(0,Math.min(days-1,Math.floor((ev.clientX-el.getBoundingClientRect().left)/cw)));}
$('grid').addEventListener('pointerdown',e=>{if(e.button!==0||(pending&&paintMode===null))return;const line=e.target.closest('.task-timeline');if(!line)return;const t=tasks.find(x=>x.id===line.dataset.id),bar=e.target.closest('.bar'),edge=e.target.dataset.edge;pointer={id:t.id,line,bar,mode:paintMode!==null?'paint':bar?(edge||'move'):'draw',x:e.clientX,y:e.clientY,index:cellAt(e,line),oldStart:t.start_date,oldEnd:t.end_date,moved:false};line.setPointerCapture(e.pointerId);e.preventDefault();});
$('grid').addEventListener('pointermove',e=>{if(!pointer)return;const p=pointer;if(p.mode==='paint'){p.endIndex=cellAt(e,p.line);paintPreview(p);return;}const delta=Math.round((e.clientX-p.x)/cw);if(Math.abs(e.clientX-p.x)>3||Math.abs(e.clientY-p.y)>3)p.moved=true;let s=p.oldStart,f=p.oldEnd;if(p.mode==='draw'){const i=cellAt(e,p.line);s=add(start,Math.min(p.index,i));f=add(start,Math.max(p.index,i));}else if(p.mode==='move'){s=add(p.oldStart,delta);f=add(p.oldEnd,delta);}else if(p.mode==='start'){s=add(p.oldStart,delta);if(s>f)s=f;}else{f=add(p.oldEnd,delta);if(f<s)f=s;}p.newStart=s;p.newEnd=f;let selection=p.line.querySelector('.selection');if(!selection){selection=document.createElement('div');selection.className='selection';p.line.append(selection);}selection.style.left=Math.max(0,diff(s,start))*cw+'px';selection.style.width=(Math.min(days,diff(f,start)+1)-Math.max(0,diff(s,start)))*cw+'px';selection.title=`${s} → ${f}`;});
async function finishPointer(e){if(!pointer)return;const p=pointer;pointer=null;p.line.querySelector('.selection')?.remove();if(p.line.hasPointerCapture(e.pointerId))p.line.releasePointerCapture(e.pointerId);suppressClick=true;setTimeout(()=>suppressClick=false,100);if(p.mode==='paint'){paintDates(p.id,Math.min(p.index,p.endIndex??p.index),Math.max(p.index,p.endIndex??p.index));return;}if(p.mode!=='draw'&&!p.moved){openEditor('tasks',p.id);return;}const s=p.newStart||(p.mode==='draw'?add(start,p.index):p.oldStart),f=p.newEnd||s;if(s!==p.oldStart||f!==p.oldEnd)await updateTask(p.id,{start_date:s,end_date:f});}
$('grid').addEventListener('pointerup',finishPointer);$('grid').addEventListener('pointercancel',()=>{pointer?.line.querySelector('.selection')?.remove();pointer=null;render();});
$('grid').addEventListener('keydown',e=>{const bar=e.target.closest('.bar');if(!bar)return;if(e.key==='Enter'||e.key===' '){e.preventDefault();openEditor('tasks',bar.dataset.id);}if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();const t=tasks.find(t=>t.id===bar.dataset.id),n=e.key==='ArrowRight'?1:-1,patch=e.shiftKey?{end_date:add(t.end_date,n)}:{start_date:add(t.start_date,n),end_date:add(t.end_date,n)};if(!e.shiftKey||patch.end_date>=t.start_date)updateTask(t.id,patch);}});
function clearDrag(){draggingId=null;draggingKind=null;document.querySelectorAll('.drop-target,.drop-before,.drop-after,.dragging').forEach(x=>x.classList.remove('drop-target','drop-before','drop-after','dragging'));}
function insertionPosition(items,targetId,after){const index=items.findIndex(x=>x.id===targetId);if(index<0)return Math.max(0,...items.map(x=>x.position))+1024;const slot=index+(after?1:0),before=items[slot-1]?.position,next=items[slot]?.position;return before===undefined?next-1024:next===undefined?before+1024:(before+next)/2;}
function dropLocation(e){const row=e.target.closest('.row');if(!row)return null;if(draggingKind==='project'){if(row.classList.contains('new-project-row'))return {row,targetId:null,after:true};const projectId=row.dataset.project;if(!projectId)return null;const header=document.querySelector(`.project-row[data-project="${projectId}"]`);return {row:header,targetId:projectId,after:e.clientY>header.getBoundingClientRect().top+header.getBoundingClientRect().height/2};}if(!row.dataset.project)return null;return {row,projectId:row.dataset.project,targetId:row.dataset.task||null,after:!!row.dataset.task&&e.clientY>row.getBoundingClientRect().top+row.getBoundingClientRect().height/2};}
$('grid').addEventListener('dragstart',e=>{const source=e.target.closest('[data-drag-task],[data-drag-project]');if(!source||pending||e.target.closest('.collapse')){e.preventDefault();return;}draggingKind=source.dataset.dragProject?'project':'task';draggingId=source.dataset.dragProject||source.dataset.dragTask;e.dataTransfer.setData('text/plain',draggingId);e.dataTransfer.effectAllowed='move';source.closest('.row').classList.add('dragging');});
$('grid').addEventListener('dragover',e=>{if(!draggingId)return;const dest=dropLocation(e);if(!dest||dest.targetId===draggingId)return;e.preventDefault();e.dataTransfer&&(e.dataTransfer.dropEffect='move');document.querySelectorAll('.drop-target,.drop-before,.drop-after').forEach(x=>x.classList.remove('drop-target','drop-before','drop-after'));dest.row.classList.add('drop-target',dest.after?'drop-after':'drop-before');});
$('grid').addEventListener('drop',async e=>{if(!draggingId)return;const dest=dropLocation(e);if(!dest)return;e.preventDefault();const id=draggingId,kind=draggingKind;clearDrag();suppressClick=true;setTimeout(()=>suppressClick=false,250);if(dest.targetId===id)return;
 if(kind==='project'){const item=projects.find(p=>p.id===id);if(!item)return;const old=item.position,siblings=projects.filter(p=>p.id!==id).sort((a,b)=>a.position-b.position),position=insertionPosition(siblings,dest.targetId,dest.after);item.position=position;projects.sort((a,b)=>a.position-b.position);render();try{const [saved]=await mutate('projects','PATCH',{position},id);if(!saved)throw Error('Project was removed. Refresh to continue.');Object.assign(item,saved);}catch(e){item.position=old;projects.sort((a,b)=>a.position-b.position);error(e);}finally{render();}}
 else{const siblings=tasks.filter(t=>t.project_id===dest.projectId&&t.id!==id).sort((a,b)=>a.position-b.position),position=insertionPosition(siblings,dest.targetId,dest.after);collapsed.delete(dest.projectId);await updateTask(id,{project_id:dest.projectId,position});tasks.sort((a,b)=>a.position-b.position);render();}});
$('grid').addEventListener('dragend',()=>{clearDrag();suppressClick=true;setTimeout(()=>suppressClick=false,250);});
function sanitize(html){const doc=new DOMParser().parseFromString(html,'text/html');const allowed=new Set(['P','DIV','BR','B','STRONG','I','EM','U','S','UL','OL','LI','BLOCKQUOTE','H2','H3','A']);for(const el of [...doc.body.querySelectorAll('*')]){if(['SCRIPT','STYLE','IFRAME','OBJECT','SVG','MATH','IMG'].includes(el.tagName)){el.remove();continue;}if(!allowed.has(el.tagName)){el.replaceWith(...el.childNodes);continue;}const href=el.getAttribute('href');for(const a of [...el.attributes])el.removeAttribute(a.name);if(el.tagName==='A'&&href&&/^https?:\/\//i.test(href)){el.setAttribute('href',href);el.setAttribute('target','_blank');el.setAttribute('rel','noopener noreferrer');}}return doc.body.innerHTML;}
function editorState(){return JSON.stringify([$ ('detail-name').value,$('detail-project').value,$('detail-status').value,$('detail-assignee').value,$('detail-start').value,$('detail-end').value,$('notes').innerHTML]);}
function openEditor(table,id){if(editor&&!closeEditor())return;const item=(table==='tasks'?tasks:projects).find(x=>x.id===id);if(!item)return;editor={table,id};$('detail-type').textContent=table==='tasks'?'TASK DETAILS':'PROJECT DETAILS';$('detail-name').value=item.name;$('task-fields').hidden=table!=='tasks';$('detail-project').innerHTML=options(item.project_id);$('detail-status').value=item.status||'assigned';$('detail-assignee').value=item.assignee||'';$('detail-start').value=item.start_date||'';$('detail-end').value=item.end_date||'';$('notes').innerHTML=sanitize(item.notes||'');$('detail-message').textContent='';$('drawer').hidden=$('drawer-shade').hidden=false;editorBaseline=editorState();$('detail-name').focus();}
function closeEditor(force=false){if(!force&&editor&&editorState()!==editorBaseline&&!confirm('Discard unsaved changes?'))return false;editor=null;$('drawer').hidden=$('drawer-shade').hidden=true;return true;}
$('close-drawer').onclick=$('drawer-shade').onclick=()=>closeEditor();document.addEventListener('keydown',e=>{if(e.key==='Escape'&&editor)closeEditor();});window.addEventListener('beforeunload',e=>{if(pending||(editor&&editorState()!==editorBaseline)){e.preventDefault();e.returnValue='';}});
$('clear-dates').onclick=()=>{$('detail-start').value=$('detail-end').value='';};
document.querySelectorAll('[data-command]').forEach(b=>{b.onmousedown=e=>e.preventDefault();b.onclick=()=>{$('notes').focus();document.execCommand(b.dataset.command,false);};});
$('add-link').onmousedown=e=>e.preventDefault();$('add-link').onclick=()=>{const url=prompt('Link URL (https://…)');if(!url)return;if(!/^https?:\/\//i.test(url)){toast('Use a full https:// or http:// URL');return;}$('notes').focus();document.execCommand('createLink',false,url);};
$('notes').addEventListener('paste',e=>{e.preventDefault();const html=e.clipboardData.getData('text/html'),plain=e.clipboardData.getData('text/plain');document.execCommand('insertHTML',false,html?sanitize(html):esc(plain).replace(/\n/g,'<br>'));});
$('detail-form').onsubmit=async e=>{e.preventDefault();if(!editor)return;const name=$('detail-name').value.trim();if(!name)return;const current={...editor},patch={name,notes:sanitize($('notes').innerHTML)};if(current.table==='tasks'){const s=$('detail-start').value,f=$('detail-end').value;if((s&&!f)||(!s&&f)||s>f){$('detail-message').textContent='Choose a valid start and finish.';return;}Object.assign(patch,{project_id:$('detail-project').value,status:$('detail-status').value,assignee:$('detail-assignee').value,start_date:s||null,end_date:f||null});}$('save-detail').disabled=true;try{const [saved]=await mutate(current.table,'PATCH',patch,current.id);if(!saved)throw Error('This item was removed. Refresh to continue.');const item=(current.table==='tasks'?tasks:projects).find(x=>x.id===current.id);Object.assign(item,saved);closeEditor(true);render();toast('Changes saved');}catch(e){$('detail-message').textContent=e.message;}finally{$('save-detail').disabled=false;}};
$('delete-item').onclick=async()=>{if(!editor)return;const current={...editor};if(!confirm(current.table==='projects'?'Delete this project and all of its tasks?':'Delete this task?'))return;$('delete-item').disabled=true;try{await mutate(current.table,'DELETE',null,current.id);if(current.table==='projects'){projects=projects.filter(x=>x.id!==current.id);tasks=tasks.filter(x=>x.project_id!==current.id);}else tasks=tasks.filter(x=>x.id!==current.id);closeEditor(true);render();toast('Deleted');}catch{}finally{$('delete-item').disabled=false;}};
load();setInterval(()=>{if(!document.hidden&&!editor&&!document.activeElement?.closest('.grid'))load(true);},15000);
